    const run = queue.then(async () => {
      const items = await load();
      const result = mutator(items); // returns {result, nextItems?}
      if (nextItems !== undefined) await save(nextItems);
      return result;
    });
    // keep queue alive even on failure
    queue = run.catch(() => {});
    return run;
  }
  async function read(reader) {
    const run = queue.then(async () => {
      const items = await load();
      return reader(items);
    });
    queue = run.catch(() => {});
    return run;
  }
  return { mutate, read };
}
