{"content": "// server/validate.js — 필드 검증 (Unicode 코드 포인트 길이, trim, enum, UUID v4 — 기준 C)
import { validationError } from './errors.js';

export const STATUSES = ['received', 'in_progress', 'completed'];
export const PRIORITIES = ['low', 'medium', 'high'];

// UUID v4 형식 검사(승인 기준 C): 형식 오류 → 400, 형식 유효·미존재 → 404는 라우트에서 처리
const UUID_V4_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function isUuidV4(value) {
  return typeof value === 'string' && UUID_V4_RE.test(value);
}

export function assertUuidFormat(id) {
  if (!isUuidV4(id)) {
    throw validationError('요청 ID가 UUID v4 형식이 아닙니다.');
  }
}

// Unicode 코드 포인트 기준 길이 (surrogate pair 2개 코드 포인트로 계산)
export function codePointLength(s) {
  return [...s].length;
}

const STRING_FIELDS = {
  title: { min: 1, max: 100 },
  requester: { min: 1, max: 60 },
  assignee: { min: 1, max: 60 },
};

const CREATE_ALLOWED_KEYS = ['title', 'description', 'requester', 'assignee', 'priority'];

function trimStringField(body, key, { min, max }) {
  const present = Object.prototype.hasOwnProperty.call(body, key);
  if (!present) {
    throw validationError(`필수 필드가 누락되었습니다: ${key}`);
  }
  const raw = body[key];
  if (typeof raw !== 'string') {
    throw validationError(`필드는 문자열이어야 합니다: ${key}`);
  }
  const trimmed = raw.trim();
  const len = codePointLength(trimmed);
  if (len < min) {
    throw validationError(`필드 값이 비어 있습니다: ${key}`);
  }
  if (len > max) {
    throw validationError(`필드 길이가 초과되었습니다: ${key} (최대 ${max})`);
  }
  return trimmed;
}

// POST /api/requests 본문 검증 → {title, description, requester, assignee, priority}
// - 알 수 없는 필드(id/status/createdAt/updatedAt 포함) → 400
// - description 생략 시 빈 문자열, 공백 trim 후 저장
export function validateCreatePayload(body) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw validationError('요청 본문은 JSON 객체여야 합니다.');
  }
  for (const key of Object.keys(body)) {
    if (!CREATE_ALLOWED_KEYS.includes(key)) {
      throw validationError(`허용되지 않는 필드입니다: ${key}`);
    }
  }
  const title = trimStringField(body, 'title', STRING_FIELDS.title);
  const requester = trimStringField(body, 'requester', STRING_FIELDS.requester);
  const assignee = trimStringField(body, 'assignee', STRING_FIELDS.assignee);

  let description = '';
  if (Object.prototype.hasOwnProperty.call(body, 'description')) {
    const raw = body.description;
    if (typeof raw !== 'string') {
      throw validationError('필드는 문자열이어야 합니다: description');
    }
    description = raw.trim();
    if (codePointLength(description) > 2000) {
      throw validationError('필드 길이가 초과되었습니다: description (최대 2000)');
    }
  }

  if (!Object.prototype.hasOwnProperty.call(body, 'priority')) {
    throw validationError('필수 필드가 누락되었습니다: priority');
  }
  const priority = body.priority;
  if (typeof priority !== 'string' || !PRIORITIES.includes(priority)) {
    throw validationError('필드 값이 유효하지 않습니다: priority');
  }

  return { title, description, requester, assignee, priority };
}

// GET /api/requests 쿼리 검증: 값이 있으면 enum, 없으면(또는 빈 문자열이면) 필터 없음
export function parseListFilters(query) {
  const filters = {};
  for (const [key, allowed] of [['status', STATUSES], ['priority', PRIORITIES]]) {
    const value = query[key];
    if (value === undefined || value === '') continue;
    if (typeof value !== 'string' || !allowed.includes(value)) {
      throw validationError(`쿼리 값이 유효하지 않습니다: ${key}`);
    }
    filters[key] = value;
  }
  return filters;
}
