{"content": "// server/store.js — JSON 파일 저장소
// - 파일 미존재 → 빈 배열로 시작, 첫 저장 시 상위 디렉터리 생성
// - 손상된 JSON → 빈 배열로 초기화하지 않고 500 INTERNAL_ERROR
// - 같은 디렉터리 임시 파일 + rename 원자적 교체
// - 읽기 포함 전체 연산(load→mutate→save)을 직렬화하는 작업 큐
//   (차후 PATCH 라우트도 mutate()/read() 재사용)
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
import { internalError } from './errors.js';

export const DEFAULT_DATA_FILE = path.resolve('data', 'requests.json');

let tmpCounter = 0;

export function createStore(options = {}) {
  const dataFile = path.resolve(options.dataFile || DEFAULT_DATA_FILE);

  // 직렬화 큐: 이전 연산이 끝난 뒤에만 다음 연산의 load→mutate→save가 실행된다.
  let queue = Promise.resolve();

  async function load() {
    let text;
    try {
      text = await readFile(dataFile, 'utf8');
    } catch (err) {
      if (err && err.code === 'ENOENT') {
        return []; // 파일 미존재 → 빈 배열로 시작
      }
      throw internalError('저장 파일을 읽을 수 없습니다.');
    }
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      throw internalError('저장 파일이 손상되었습니다.'); // 조용한 초기화 금지
    }
    if (!Array.isArray(parsed)) {
      throw internalError('저장 파일이 손상되었습니다.');
    }
    return parsed;
  }

  async function save(items) {
    const dir = path.dirname(dataFile);
    await mkdir(dir, { recursive: true });
    // 같은 디렉터리의 고유 임시 파일에 쓰고 rename으로 원자적 교체
    tmpCounter += 1;
    const tmp = path.join(
      dir,
      `.${path.basename(dataFile)}.${process.pid}.${Date.now()}.${tmpCounter}.tmp`
    );
    const text = JSON.stringify(items, null, 2);
    await writeFile(tmp, text, 'utf8');
    await rename(tmp, dataFile);
  }

  // 읽기 전용 연산 (목록·상세 등). 큐에 연결되어 쓰기와 직렬화된다.
  function read(reader) {
    const run = queue.then(async () => {
      const items = await load();
      return reader(items);
    });
    queue = run.catch(() => {}); // 실패해도 큐는 유지
    return run;
  }

  // 변경 연산: mutator(items) → { result, next }
  // next를 반환하면 저장하고, 반환하지 않으면 저장 없이 결과만 반환한다.
  // (차후 PATCH: 동일 값이면 next 없이 200 + updatedAt 유지에 재사용 가능)
  function mutate(mutator) {
    const run = queue.then(async () => {
      const items = await load();
      const { result, next } = await mutator(items);
      if (next !== undefined) {
        await save(next);
      }
      return result;
    });
    queue = run.catch(() => {});
    return run;
  }

  return { dataFile, read, mutate };
}
