import { Router } from 'express';
import { randomUUID } from 'node:crypto';
import { notFoundError, validationError } from './errors.js';
import { assertUuidFormat, parseListFilters, validateCreatePayload } from './validate.js';

// Express 4는 async 핸들러의 reject를 자동 전파하지 않으므로 래핑한다.
function asyncHandler(handler) {
  return (req, res, next) => {
    Promise.resolve(handler(req, res, next)).catch(next);
  };
}

// createdAt 내림차순, 동률이면 id 오름차순 (ISO 8601 문자열 비교로 충분)
function compareNewestFirst(a, b) {
  if (a.createdAt !== b.createdAt) {
    return a.createdAt < b.createdAt ? 1 : -1;
  }
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export function createRequestRoutes(store) {
  const router = Router();

  // POST /api/requests — 등록 (REQ-001, AC-001/002/013)
  router.post(
    '/requests',
    asyncHandler(async (req, res) => {
      const payload = validateCreatePayload(req.body);
      const created = await store.mutate((items) => {
        const now = new Date().toISOString(); // UTC ISO 8601
        const record = {
          id: randomUUID(), // UUID v4
          title: payload.title,
