  router.get(
    '/requests/:id',
    asyncHandler(async (req, res) => {
      assertUuidFormat(req.params.id); // 형식 오류 → 400 VALIDATION_ERROR
      const item = await store.read((items) => {
        const found = items.find((entry) => entry.id === req.params.id);
        if (!found) throw notFoundError();
        return found;
      });
      res.status(200).json(item);
    })
  );

  return router;
