// 고정 테스트 계약: export function createApp({dataFile})
import express from 'express';
import { createStore } from './store.js';
import { createRequestRoutes } from './routes.js';
import { HttpError, errorResponse, errorStatus } from './errors.js';

export function createApp(options = {}) {
  const app = express();
  // express.json() 파싱 실패(잘못된 JSON)는 아래 오류 미들웨어에서 400으로 변환
  app.use(express.json());

  // dataFile 옵션이 없으면 store가 작업 디렉터리 기준 ./data/requests.json 사용
  const store = createStore(options.dataFile ? { dataFile: options.dataFile } : {});
  app.use('/api', createRequestRoutes(store));

  // 오류 응답 미들웨어: {error:{code,message}} — 스택·서버 경로 노출 금지
  app.use((err, req, res, next) => {
    // body-parser의 JSON 파싱 실패 → 400 VALIDATION_ERROR (원본 메시지 대신 고정 문구)
    if (err && (err.type === 'entity.parse.failed' || err instanceof SyntaxError)) {
      return res.status(400).json({
        error: { code: 'VALIDATION_ERROR', message: '잘못된 JSON 형식입니다.' },
      });
    }
    if (!(err instanceof HttpError)) {
      // 콘솔 로그는 서버 프로세스 출력이며 응답에는 포함되지 않는다.
      console.error('Unhandled error:', err);
    }
    return res.status(errorStatus(err)).json(errorResponse(err));
  });

  return app;
}
