{"content": "1|// server/validate.js — 필드 검증 (Unicode 코드 포인트 길이, trim, enum, UUID v4 — 기준 C)
2|import { validationError } from './errors.js';
3|
4|export const STATUSES = ['received', 'in_progress', 'completed'];
5|export const PRIORITIES = ['low', 'medium', 'high'];
6|
7|// UUID v4 형식 검사(승인 기준 C): 형식 오류 → 400, 형식 유효·미존재 → 404는 라우트에서 처리
8|const UUID_V4_RE =
9|  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
10|
11|export function isUuidV4(value) {
12|  return typeof value === 'string' && UUID_V4_RE.test(value);
13|}
14|
15|export function assertUuidFormat(id) {
16|  if (!isUuidV4(id)) {
17|    throw validationError('요청 ID가 UUID v4 형식이 아닙니다.');
18|  }
19|}
20|
21|// Unicode 코드 포인트 기준 길이 (surrogate pair 2개 코드 포인트로 계산)
22|export function codePointLength(s) {
23|  return [...s].length;
24|}
25|
26|const STRING_FIELDS = {
27|  title: { min: 1, max: 100 },
28|  requester: { min: 1, max: 60 },
29|  assignee: { min: 1, max: 60 },
30|};
31|
32|const CREATE_ALLOWED_KEYS = ['title', 'description', 'requester', 'assignee', 'priority'];
33|
34|function trimStringField(body, key, { min, max }) {
35|  const present = Object.prototype.hasOwnProperty.call(body, key);
36|  if (!present) {
37|    throw validationError(`필수 필드가 누락되었습니다: ${key}`);
38|  }
39|  const raw = body[key];
40|  if (typeof raw !== 'string') {
41|    throw validationError(`필드는 문자열이어야 합니다: ${key}`);
42|  }
43|  const trimmed = raw.trim();
44|  const len = codePointLength(trimmed);
45|  if (len < min) {
46|    throw validationError(`필드 값이 비어 있습니다: ${key}`);
47|  }
48|  if (len > max) {
49|    throw validationError(`필드 길이가 초과되었습니다: ${key} (최대 ${max})`);
50|  }
51|  return trimmed;
52|}
53|
54|// POST /api/requests 본문 검증 → {title, description, requester, assignee, priority}
55|// - 알 수 없는 필드(id/status/createdAt/updatedAt 포함) → 400
56|// - description 생략 시 빈 문자열, 공백 trim 후 저장
57|export function validateCreatePayload(body) {
58|  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
59|    throw validationError('요청 본문은 JSON 객체여야 합니다.');
60|  }
61|  for (const key of Object.keys(body)) {
62|    if (!CREATE_ALLOWED_KEYS.includes(key)) {
63|      throw validationError(`허용되지 않는 필드입니다: ${key}`);
64|    }
65|  }
66|  const title = trimStringField(body, 'title', STRING_FIELDS.title);
67|  const requester = trimStringField(body, 'requester', STRING_FIELDS.requester);
68|  const assignee = trimStringField(body, 'assignee', STRING_FIELDS.assignee);
69|
70|  let description = '';
71|  if (Object.prototype.hasOwnProperty.call(body, 'description')) {
72|    const raw = body.description;
73|    if (typeof raw !== 'string') {
74|      throw validationError('필드는 문자열이어야 합니다: description');
75|    }
76|    description = raw.trim();
77|    if (codePointLength(description) > 2000) {
78|      throw validationError('필드 길이가 초과되었습니다: description (최대 2000)');
79|    }
80|  }
81|
82|  if (!Object.prototype.hasOwnProperty.call(body, 'priority')) {
83|    throw validationError('필수 필드가 누락되었습니다: priority');
84|  }
85|  const priority = body.priority;
86|  if (typeof priority !== 'string' || !PRIORITIES.includes(priority)) {
87|    throw validationError('필드 값이 유효하지 않습니다: priority');
88|  }
89|
90|  return { title, description, requester, assignee, priority };
91|}
92|
93|// GET /api/requests 쿼리 검증: 값이 있으면 enum, 없으면(또는 빈 문자열이면) 필터 없음
94|export function parseListFilters(query) {
95|  const filters = {};
96|  for (const [key, allowed] of [['status', STATUSES], ['priority', PRIORITIES]]) {
97|    const value = query[key];
98|    if (value === undefined || value === '') continue;
99|    if (typeof value !== 'string' || !allowed.includes(value)) {
100|      throw validationError(`쿼리 값이 유효하지 않습니다: ${key}`);
101|    }
102|    filters[key] = value;
103|  }
104|  return filters;
105|}", "total_lines": 105, "file_size": 3991, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// server/store.js — JSON 파일 저장소
2|// - 파일 미존재 → 빈 배열로 시작, 첫 저장 시 상위 디렉터리 생성
3|// - 손상된 JSON → 빈 배열로 초기화하지 않고 500 INTERNAL_ERROR
4|// - 같은 디렉터리 임시 파일 + rename 원자적 교체
5|// - 읽기 포함 전체 연산(load→mutate→save)을 직렬화하는 작업 큐
6|//   (차후 PATCH 라우트도 mutate()/read() 재사용)
7|import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
8|import path from 'node:path';
9|import { internalError } from './errors.js';
10|
11|export const DEFAULT_DATA_FILE = path.resolve('data', 'requests.json');
12|
13|let tmpCounter = 0;
14|
15|export function createStore(options = {}) {
16|  const dataFile = path.resolve(options.dataFile || DEFAULT_DATA_FILE);
17|
18|  // 직렬화 큐: 이전 연산이 끝난 뒤에만 다음 연산의 load→mutate→save가 실행된다.
19|  let queue = Promise.resolve();
20|
21|  async function load() {
22|    let text;
23|    try {
24|      text = await readFile(dataFile, 'utf8');
25|    } catch (err) {
26|      if (err && err.code === 'ENOENT') {
27|        return []; // 파일 미존재 → 빈 배열로 시작
28|      }
29|      throw internalError('저장 파일을 읽을 수 없습니다.');
30|    }
31|    let parsed;
32|    try {
33|      parsed = JSON.parse(text);
34|    } catch {
35|      throw internalError('저장 파일이 손상되었습니다.'); // 조용한 초기화 금지
36|    }
37|    if (!Array.isArray(parsed)) {
38|      throw internalError('저장 파일이 손상되었습니다.');
39|    }
40|    return parsed;
41|  }
42|
43|  async function save(items) {
44|    const dir = path.dirname(dataFile);
45|    await mkdir(dir, { recursive: true });
46|    // 같은 디렉터리의 고유 임시 파일에 쓰고 rename으로 원자적 교체
47|    tmpCounter += 1;
48|    const tmp = path.join(
49|      dir,
50|      `.${path.basename(dataFile)}.${process.pid}.${Date.now()}.${tmpCounter}.tmp`
51|    );
52|    const text = JSON.stringify(items, null, 2);
53|    await writeFile(tmp, text, 'utf8');
54|    await rename(tmp, dataFile);
55|  }
56|
57|  // 읽기 전용 연산 (목록·상세 등). 큐에 연결되어 쓰기와 직렬화된다.
58|  function read(reader) {
59|    const run = queue.then(async () => {
60|      const items = await load();
61|      return reader(items);
62|    });
63|    queue = run.catch(() => {}); // 실패해도 큐는 유지
64|    return run;
65|  }
66|
67|  // 변경 연산: mutator(items) → { result, next }
