{"content": "1|// server/app.js — createApp(options): Supertest가 포트 없이 검사하는 Express 앱
2|// 고정 테스트 계약: export function createApp({dataFile})
3|import express from 'express';
4|import { createStore } from './store.js';
5|import { createRequestRoutes } from './routes.js';
6|import { HttpError, errorResponse, errorStatus } from './errors.js';
7|
8|export function createApp(options = {}) {
9|  const app = express();
10|  // express.json() 파싱 실패(잘못된 JSON)는 아래 오류 미들웨어에서 400으로 변환
11|  app.use(express.json());
12|
13|  // dataFile 옵션이 없으면 store가 작업 디렉터리 기준 ./data/requests.json 사용
14|  const store = createStore(options.dataFile ? { dataFile: options.dataFile } : {});
15|  app.use('/api', createRequestRoutes(store));
16|
17|  // 오류 응답 미들웨어: {error:{code,message}} — 스택·서버 경로 노출 금지
18|  app.use((err, req, res, next) => {
19|    // body-parser의 JSON 파싱 실패 → 400 VALIDATION_ERROR (원본 메시지 대신 고정 문구)
20|    if (err && (err.type === 'entity.parse.failed' || err instanceof SyntaxError)) {
21|      return res.status(400).json({
22|        error: { code: 'VALIDATION_ERROR', message: '잘못된 JSON 형식입니다.' },
23|      });
24|    }
25|    if (!(err instanceof HttpError)) {
26|      // 콘솔 로그는 서버 프로세스 출력이며 응답에는 포함되지 않는다.
27|      console.error('Unhandled error:', err);
28|    }
29|    return res.status(errorStatus(err)).json(errorResponse(err));
30|  });
31|
32|  return app;
