{"content": "1|// server/errors.js — 오류 코드·포맷 ({error:{code,message}}), 스택·경로 노출 금지
2|export const ERROR_CODES = {
3|  VALIDATION_ERROR: 400,
4|  NOT_FOUND: 404,
5|  INVALID_TRANSITION: 409,
6|  INTERNAL_ERROR: 500,
7|};
8|
9|export class HttpError extends Error {
10|  constructor(status, code, message) {
11|    super(message);
12|    this.name = 'HttpError';
13|    this.status = status;
14|    this.code = code;
15|  }
16|}
17|
18|export function validationError(message = '입력 값이 유효하지 않습니다.') {
19|  return new HttpError(400, 'VALIDATION_ERROR', message);
20|}
21|
22|export function notFoundError(message = '요청을 찾을 수 없습니다.') {
23|  return new HttpError(404, 'NOT_FOUND', message);
24|}
25|
26|export function internalError(message = '내부 서버 오류가 발생했습니다.') {
27|  return new HttpError(500, 'INTERNAL_ERROR', message);
28|}
29|
30|// 응답 본문 작성: HttpError가 아니면 내부 오류로 통일(스택·경로 노출 금지)
31|export function errorResponse(err) {
32|  if (err instanceof HttpError) {
33|    return { error: { code: err.code, message: err.message } };
34|  }
35|  return { error: { code: 'INTERNAL_ERROR', message: '내부 서버 오류가 발생했습니다.' } };
36|}
