7|import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
8|import path from 'node:path';
9|import { internalError } from './errors.js';
10|
11|export const DEFAULT_DATA_FILE = path.resolve('data', 'requests.json');
12|
13|let tmpCounter = 0;
14|
15|export function createStore(options = {}) {
16|  const dataFile = path.resolve(options.dataFile || DEFAULT_DATA_FILE);
17|
18|  // 직렬화 큐: 이전 연산이 끝난 뒤에만 다음 연산의 load→mutate→save가 실행된다.
19|  let queue = Promise.resolve();
20|
21|  async function load() {
22|    let text;
23|    try {
24|      text = await readFile(dataFile, 'utf8');
25|    } catch (err) {
26|      if (err && err.code === 'ENOENT') {
27|        return []; // 파일 미존재 → 빈 배열로 시작
28|      }
29|      throw internalError('저장 파일을 읽을 수 없습니다.');
30|    }
31|    let parsed;
32|    try {
33|      parsed = JSON.parse(text);
34|    } catch {
35|      throw internalError('저장 파일이 손상되었습니다.'); // 조용한 초기화 금지
36|    }
37|    if (!Array.isArray(parsed)) {
38|      throw internalError('저장 파일이 손상되었습니다.');
39|    }
40|    return parsed;
41|  }
42|
43|  async function save(items) {
44|    const dir = path.dirname(dataFile);
45|    await mkdir(dir, { recursive: true });
46|    // 같은 디렉터리의 고유 임시 파일에 쓰고 rename으로 원자적 교체
47|    tmpCounter += 1;
48|    const tmp = path.join(
49|      dir,
50|      `.${path.basename(dataFile)}.${process.pid}.${Date.now()}.${tmpCounter}.tmp`
51|    );
52|    const text = JSON.stringify(items, null, 2);
53|    await writeFile(tmp, text, 'utf8');
54|    await rename(tmp, dataFile);
55|  }
