58|  function read(reader) {
59|    const run = queue.then(async () => {
60|      const items = await load();
61|      return reader(items);
62|    });
63|    queue = run.catch(() => {}); // 실패해도 큐는 유지
64|    return run;
65|  }
66|
67|  // 변경 연산: mutator(items) → { result, next }
68|  // next를 반환하면 저장하고, 반환하지 않으면 저장 없이 결과만 반환한다.
69|  // (차후 PATCH: 동일 값이면 next 없이 200 + updatedAt 유지에 재사용 가능)
70|  function mutate(mutator) {
71|    const run = queue.then(async () => {
72|      const items = await load();
73|      const { result, next } = await mutator(items);
74|      if (next !== undefined) {
75|        await save(next);
76|      }
77|      return result;
78|    });
79|    queue = run.catch(() => {});
80|    return run;
81|  }
82|
83|  return { dataFile, read, mutate };
