2|// PATCH /api/requests/:id와 PATCH /api/requests/:id/status는 다음 교시 범위(미구현).
3|import { Router } from 'express';
4|import { randomUUID } from 'node:crypto';
5|import { notFoundError } from './errors.js';
6|import { assertUuidFormat, parseListFilters, validateCreatePayload } from './validate.js';
7|
8|// Express 4는 async 핸들러의 reject를 자동 전파하지 않으므로 래핑한다.
9|function asyncHandler(handler) {
10|  return (req, res, next) => {
11|    Promise.resolve(handler(req, res, next)).catch(next);
12|  };
13|}
14|
15|// createdAt 내림차순, 동률이면 id 오름차순 (ISO 8601 문자열 비교로 충분)
16|function compareNewestFirst(a, b) {
17|  if (a.createdAt !== b.createdAt) {
18|    return a.createdAt < b.createdAt ? 1 : -1;
19|  }
20|  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
21|}
22|
23|export function createRequestRoutes(store) {
24|  const router = Router();
25|
26|  // POST /api/requests — 등록 (REQ-001, AC-001/002/013)
27|  router.post(
28|    '/requests',
29|    asyncHandler(async (req, res) => {
30|      const payload = validateCreatePayload(req.body);
31|      const created = await store.mutate((items) => {
32|        const now = new Date().toISOString(); // UTC ISO 8601
33|        const record = {
34|          id: randomUUID(), // UUID v4
35|          title: payload.title,
36|          description: payload.description,
37|          requester: payload.requester,
38|          assignee: payload.assignee,
39|          priority: payload.priority,
40|          status: 'received',
41|          createdAt: now,
42|          updatedAt: now,
43|        };
44|        return { result: record, next: [...items, record] };
45|      });
46|      res.status(201).json(created);
47|    })
48|  );
49|
50|  // GET /api/requests — 목록·AND 필터·정렬, total = 필터 적용 후 items.length (기준 A)
51|  router.get(
52|    '/requests',
53|    asyncHandler(async (req, res) => {
54|      const filters = parseListFilters(req.query);
55|      const items = await store.read((all) => {
56|        const filtered = all.filter((item) => {
57|          if (filters.status !== undefined && item.status !== filters.status) return false;
58|          if (filters.priority !== undefined && item.priority !== filters.priority) return false;
59|          return true;
60|        });
61|        filtered.sort(compareNewestFirst);
62|        return filtered;
63|      });
64|      res.status(200).json({ items, total: items.length });
65|    })
66|  );
67|
68|  // GET /api/requests/:id — 상세 (기준 C: 형식 오류 400 / 유효·미존재 404)
69|  router.get(
70|    '/requests/:id',
71|    asyncHandler(async (req, res) => {
72|      assertUuidFormat(req.params.id); // 형식 오류 → 400 VALIDATION_ERROR
73|      const item = await store.read((items) => {
74|        const found = items.find((entry) => entry.id === req.params.id);
75|        if (!found) throw notFoundError();
76|        return found;
77|      });
78|      res.status(200).json(item);
79|    })
80|  );
81|
82|  return router;
