```ts
import type { WorkRequest, CreateRequestPayload, RequestStatus, RequestPriority } from './types';

export class ApiError extends Error {
  constructor(readonly status: number, readonly code: string, message: string) { super(message); this.name='ApiError'; }
}

export interface ListFilters { status?: RequestStatus; priority?: RequestPriority; }
export interface ListResult { items: WorkRequest[]; total: number; }

async function parseError(res: Response): Promise<ApiError> {
  let code = 'UNKNOWN_ERROR'; let message = `요청이 실패했습니다 (HTTP ${res.status})`;
  try { const body = await res.json(); if (body && typeof body==='object' && body.error && typeof body.error.code==='string') { code=body.error.code; message=body.error.message; } } catch {}
  return new ApiError(res.status, code, message);
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, { headers: {'Accept':'application/json', ...init?.headers}, ...init });
  } catch {
    throw new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다. 네트워크 상태를 확인하세요.');
  }
  if (!res.ok) throw await parseError(res);
  try { return await res.json() as T; } catch { throw new ApiError(res.status,'PARSE_ERROR','응답을 해석할 수 없습니다.'); }
}

export function listRequests(filters: ListFilters = {}): Promise<ListResult> {
  const params = new URLSearchParams();
  if (filters.status) params.set('status', filters.status);
  if (filters.priority) params.set('priority', filters.priority);
  const qs = params.toString();
  return request(`/api/requests${qs ? `?${qs}` : ''}`);
}
export function getRequest(id: string): Promise<WorkRequest> { return request(`/api/requests/${encodeURIComponent(id)}`); }
export function createRequest(payload: CreateRequestPayload): Promise<WorkRequest> {
  return request('/api/requests', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) });
}
```

