{"content": "// client/src/api.ts — fetch 래퍼 (Vite 프록시의 /api 상대 경로 사용, 절대 URL 없음)
import type { CreateRequestPayload, ListFilters, RequestList, WorkRequest } from './types';

/** 오류 형식: {error:{code,message}} (docs/specification.md API 오류 조항) */
export class ApiError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
  }
}

/** 오류 응답 본문 파싱 (본문 형식이 다르면 일반 오류로 통일) */
async function toApiError(res: Response): Promise<ApiError> {
  let code = 'UNKNOWN_ERROR';
  let message = `요청이 실패했습니다. (HTTP ${res.status})`;
  try {
    const body: unknown = await res.json();
    if (isErrorBody(body)) {
      code = body.error.code;
      message = body.error.message;
    }
  } catch {
    // JSON이 아니면 기본 문구 사용
  }
  return new ApiError(res.status, code, message);
}

function isErrorBody(body: unknown): body is { error: { code: string; message: string } } {
  if (body === null || typeof body !== 'object') return false;
  const error = (body as { error?: unknown }).error;
  if (error === null || typeof error !== 'object') return false;
  const { code, message } = error as { code?: unknown; message?: unknown };
  return typeof code === 'string' && typeof message === 'string';
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, init);
  } catch {
    // 네트워크 오류는 HTTP 상태와 구분된다
    throw new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다. 네트워크 상태를 확인하고 다시 시도하세요.');
  }
  if (!res.ok) {
    throw await toApiError(res);
  }
  try {
    return (await res.json()) as T;
  } catch {
    throw new ApiError(res.status, 'PARSE_ERROR', '서버 응답을 해석할 수 없습니다.');
  }
}

/** GET /api/requests — 상태·우선순위 AND 필터, total=필터 후 개수 */
export function listRequests(filters: ListFilters = {}): Promise<RequestList> {
  const params = new URLSearchParams();
  if (filters.status) {
    params.set('status', filters.status);
  }
  if (filters.priority) {
    params.set('priority', filters.priority);
  }
  const query = params.toString();
  return request<RequestList>(`/api/requests${query ? `?${query}` : ''}`);
}

/** GET /api/requests/{id} — 상세 (404는 ApiError status=404, code=NOT_FOUND) */
export function getRequest(id: string): Promise<WorkRequest> {
  return request<WorkRequest>(`/api/requests/${encodeURIComponent(id)}`);
}

/** POST /api/requests — 등록 (성공 시 201 + 생성된 WorkRequest) */
export function createRequest(payload: CreateRequestPayload): Promise<WorkRequest> {
  return request<WorkRequest>('/api/requests', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
}
