import { useCallback, useEffect, useState } from 'react';
import { ApiError, listRequests } from '../api';
import { priorityLabel, statusLabel } from '../labels';
import {
  REQUEST_PRIORITIES,
  REQUEST_STATUSES,
  type ListFilters,
  type RequestList,
} from '../types';

type LoadState =
  | { phase: 'loading' }
  | { phase: 'error'; error: ApiError }
  | { phase: 'success'; data: RequestList };

interface Props {
  /** 상세 화면으로 이동 (해시 라우팅) */
  onOpenDetail: (id: string) => void;
  /** 등록 화면으로 이동 */
  onOpenCreate: () => void;
}

export function RequestList({ onOpenDetail, onOpenCreate }: Props) {
  const [filters, setFilters] = useState<ListFilters>({});
  const [state, setState] = useState<LoadState>({ phase: 'loading' });
  const [reloadToken, setReloadToken] = useState(0);

  const load = useCallback((currentFilters: ListFilters) => {
    setState({ phase: 'loading' });
    listRequests(currentFilters)
      .then((data) => setState({ phase: 'success', data }))
      .catch((error: unknown) => {
        setState({
          phase: 'error',
          error:
            error instanceof ApiError
              ? error
              : new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다.'),
        });
      });
  }, []);

  useEffect(() => {
    load(filters);
  }, [load, filters, reloadToken]);

  function changeStatus(value: string) {
    setFilters((prev) => ({
      ...prev,
      status: value === '' ? undefined : (value as ListFilters['status']),
    }));
  }

  function changePriority(value: string) {
    setFilters((prev) => ({
      ...prev,
      priority: value === '' ? undefined : (value as ListFilters['priority']),
    }));
  }

  return (
    <section aria-labelledby="list-heading">
      <div className="app-header">
        <h1 id="list-heading">AI Work Request Manager 2.0</h1>
        <button type="button" className="btn btn-primary" onClick={onOpenCreate}>
          + 요청 등록
        </button>
      </div>

      <div className="list-toolbar">
        <label className="form-field">
          상태{' '}
          <select
            aria-label="상태 필터"
            value={filters.status ?? ''}
            onChange={(e) => changeStatus(e.target.value)}
          >
            <option value="">전체</option>
            {REQUEST_STATUSES.map((status) => (
              <option key={status} value={status}>
                {statusLabel(status)}
              </option>
            ))}
          </select>
        </label>

        <label className="form-field">
          우선순위{' '}
          <select
            aria-label="우선순위 필터"
            value={filters.priority ?? ''}
            onChange={(e) => changePriority(e.target.value)}
          >
            <option value="">전체</option>
            {REQUEST_PRIORITIES.map((priority) => (
              <option key={priority} value={priority}>
                {priorityLabel(priority)}
              </option>
            ))}
          </select>
        </label>

        <p className="list-count" aria-live="polite">
          {state.phase === 'success' ? `총 ${state.data.total}건` : '총 -건'}
        </p>
      </div>

      {state.phase === 'loading' && (
        <div className="state-box" role="status">
          로딩 중...
        </div>
      )}

      {state.phase === 'error' && (
        <div className="state-box" role="alert">
          <p className="error-text">{state.error.message}</p>
          <button type="button" className="btn" onClick={() => setReloadToken((n) => n + 1)}>
            재시도
          </button>
        </div>
      )}

      {state.phase === 'success' &&
        (state.data.items.length === 0 ? (
          <div className="state-box" role="status">
            결과 없음
          </div>
        ) : (
          <div className="table-wrap">
            <table className="requests-table">
              <thead>
                <tr>
                  <th scope="col">ID</th>
                  <th scope="col">제목</th>
                  <th scope="col">상태</th>
                  <th scope="col">우선순위</th>
                  <th scope="col">담당자</th>
                </tr>
              </thead>
              <tbody>
                {state.data.items.map((item) => (
                  <tr key={item.id}>
                    <td data-label="ID">{shortId(item.id)}</td>
                    <td data-label="제목">
                      <button
                        type="button"
                        className="title-link"
                        onClick={() => onOpenDetail(item.id)}
                      >
                        {item.title}
                      </button>
                    </td>
                    <td data-label="상태">{statusLabel(item.status)}</td>
                    <td data-label="우선순위">{priorityLabel(item.priority)}</td>
                    <td data-label="담당자">{item.assignee}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}
    </section>
  );
}

/** 표시용: ID는 와이어프레임 대로 축약해 표시(원본 데이터는 변경하지 않음) */
function shortId(id: string): string {
  return `${id.slice(0, 8)}…`;
}
