import { useState, type FormEvent } from 'react';
import { ApiError, createRequest } from '../api';
import { PRIORITY_LABELS } from '../labels';
import { REQUEST_PRIORITIES, type RequestPriority } from '../types';

interface FormValues {
  title: string;
  description: string;
  requester: string;
  assignee: string;
  priority: '' | RequestPriority;
}

interface FieldErrors {
  title?: string;
  description?: string;
  requester?: string;
  assignee?: string;
  priority?: string;
}

interface Props {
  /** 목록으로 돌아가기 (취소) */
  onCancel: () => void;
  /** POST 201 성공 후 상세 화면으로 이동 */
  onCreated: (id: string) => void;
}

/** Unicode 코드 포인트 기준 길이 (docs/specification.md) */
function codePointLength(value: string): number {
  return [...value].length;
}

/** 계약 검증: 필수·길이·공백만 있는 값 */
function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  const title = values.title.trim();
  if (title.length === 0) {
    errors.title = '제목은 필수입니다.';
  } else if (codePointLength(title) > 100) {
    errors.title = '제목은 100자 이내로 입력하세요.';
  }

  const description = values.description.trim();
  if (codePointLength(description) > 2000) {
    errors.description = '설명은 2000자 이내로 입력하세요.';
  }

  const requester = values.requester.trim();
  if (requester.length === 0) {
    errors.requester = '요청자는 필수입니다.';
  } else if (codePointLength(requester) > 60) {
    errors.requester = '요청자는 60자 이내로 입력하세요.';
  }

  const assignee = values.assignee.trim();
  if (assignee.length === 0) {
    errors.assignee = '담당자는 필수입니다.';
  } else if (codePointLength(assignee) > 60) {
    errors.assignee = '담당자는 60자 이내로 입력하세요.';
  }

  if (values.priority === '') {
    errors.priority = '우선순위를 선택하세요.';
  }

  return errors;
}

const EMPTY_VALUES: FormValues = {
  title: '',
  description: '',
  requester: '',
  assignee: '',
  priority: '',
};

export function RequestForm({ onCancel, onCreated }: Props) {
  const [values, setValues] = useState<FormValues>(EMPTY_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [serverError, setServerError] = useState<string | null>(null);

  // 오류 시 입력 보존: 값을 초기화하지 않고 그대로 유지한다.
  function setField<K extends keyof FormValues>(key: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) {
      return; // 재클릭·Enter 중복 제출 방지
    }
    const nextErrors = validate(values);
    setErrors(nextErrors);
    setServerError(null);
    if (Object.keys(nextErrors).length > 0) {
      return;
    }
    setSubmitting(true);
    try {
      const created = await createRequest({
        title: values.title.trim(),
        description: values.description.trim(),
        requester: values.requester.trim(),
        assignee: values.assignee.trim(),
        priority: values.priority as RequestPriority,
      });
      onCreated(created.id); // 성공 시 상세 화면으로 이동
    } catch (error: unknown) {
      const message =
        error instanceof ApiError
          ? error.message
          : '서버에 연결할 수 없습니다. 네트워크 상태를 확인하고 다시 시도하세요.';
      setServerError(message);
      setSubmitting(false);
    }
  }

  const hasError = (key: keyof FieldErrors): boolean => Object.prototype.hasOwnProperty.call(errors, key);

  return (
    <section aria-labelledby="create-heading">
      <div className="panel">
        <button type="button" className="link-as-text" onClick={onCancel}>
          목록으로
        </button>
        <h1 id="create-heading">새 업무 요청</h1>

        <form noValidate onSubmit={handleSubmit} aria-busy={submitting}>
          <div className="form-field">
            <label htmlFor="f-title">
              제목 <span className="required-mark" aria-hidden="true">*</span>
              <span className="sr-only-text">(필수)</span>
            </label>
            <input
              type="text"
              id="f-title"
              name="title"
              value={values.title}
              onChange={(e) => setField('title', e.target.value)}
              aria-required="true"
              aria-invalid={hasError('title')}
              aria-describedby={hasError('title') ? 'err-title' : undefined}
            />
            {hasError('title') && (
              <p className="field-error" id="err-title" role="alert">
                {errors.title}
              </p>
            )}
          </div>

          <div className="form-field">
            <label htmlFor="f-description">설명</label>
            <textarea
              id="f-description"
              name="description"
              value={values.description}
              onChange={(e) => setField('description', e.target.value)}
              aria-invalid={hasError('description')}
              aria-describedby={hasError('description') ? 'err-description' : undefined}
            />
            <p className="hint">최대 2000자</p>
            {hasError('description') && (
              <p className="field-error" id="err-description" role="alert">
                {errors.description}
              </p>
            )}
          </div>

          <div className="form-field">
            <label htmlFor="f-requester">
              요청자 <span className="required-mark" aria-hidden="true">*</span>
              <span className="sr-only-text">(필수)</span>
            </label>
            <input
              type="text"
              id="f-requester"
              name="requester"
              value={values.requester}
              onChange={(e) => setField('requester', e.target.value)}
              aria-required="true"
              aria-invalid={hasError('requester')}
              aria-describedby={hasError('requester') ? 'err-requester' : undefined}
            />
            {hasError('requester') && (
              <p className="field-error" id="err-requester" role="alert">
                {errors.requester}
              </p>
            )}
          </div>

          <div className="form-field">
            <label htmlFor="f-assignee">
              담당자 <span className="required-mark" aria-hidden="true">*</span>
              <span className="sr-only-text">(필수)</span>
            </label>
            <input
              type="text"
              id="f-assignee"
              name="assignee"
              value={values.assignee}
              onChange={(e) => setField('assignee', e.target.value)}
              aria-required="true"
              aria-invalid={hasError('assignee')}
              aria-describedby={hasError('assignee') ? 'err-assignee' : undefined}
            />
            {hasError('assignee') && (
              <p className="field-error" id="err-assignee" role="alert">
                {errors.assignee}
              </p>
            )}
          </div>

          <fieldset className="form-field" style={{ border: 'none', padding: 0 }}>
            <legend>
              우선순위 <span className="required-mark" aria-hidden="true">*</span>
              <span className="sr-only-text">(필수)</span>
            </legend>
            <div className="radio-group" role="radiogroup" aria-label="우선순위">
              {REQUEST_PRIORITIES.map((priority) => (
                <label className="radio-option" key={priority}>
                  <input
                    type="radio"
                    name="priority"
                    value={priority}
                    checked={values.priority === priority}
                    onChange={() => setField('priority', priority)}
                  />
                  {PRIORITY_LABELS[priority]}
                </label>
              ))}
            </div>
            {hasError('priority') && (
              <p className="field-error" id="err-priority" role="alert">
                {errors.priority}
              </p>
            )}
          </fieldset>

          {serverError && (
            <p className="field-error" role="alert">
              {serverError}
            </p>
          )}

          <div className="form-actions">
            <button type="button" className="btn" onClick={onCancel}>
              취소
            </button>
            <button type="submit" className="btn btn-primary" disabled={submitting}>
              {submitting ? '등록 중...' : '등록'}
            </button>
          </div>
        </form>
      </div>
    </section>
  );
}
