{"content": "// client/src/components/RequestDetail.tsx — WF-03 상세 화면 (읽기 전용)
// PATCH 수정·상태 변경은 다음 교시 범위이므로 이 화면에는 해당 조작을 두지 않는다.
import { useCallback, useEffect, useState } from 'react';
import { ApiError, getRequest } from '../api';
import { formatDateTime, priorityLabel, statusLabel } from '../labels';
import type { WorkRequest } from '../types';

type DetailState =
  | { phase: 'loading' }
  | { phase: 'notfound' }
  | { phase: 'error'; error: ApiError }
  | { phase: 'success'; item: WorkRequest };

interface Props {
  id: string;
  /** 목록으로 돌아가기 */
  onBack: () => void;
}

export function RequestDetail({ id, onBack }: Props) {
  const [state, setState] = useState<DetailState>({ phase: 'loading' });
  const [reloadToken, setReloadToken] = useState(0);

  const load = useCallback(() => {
    setState({ phase: 'loading' });
    getRequest(id)
      .then((item) => setState({ phase: 'success', item }))
      .catch((error: unknown) => {
        if (error instanceof ApiError && error.status === 404) {
          setState({ phase: 'notfound' });
        } else {
          setState({
            phase: 'error',
            error:
              error instanceof ApiError
                ? error
                : new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다.'),
          });
        }
      });
  }, [id]);

  useEffect(() => {
    load();
  }, [load, reloadToken]);

  return (
    <section aria-labelledby="detail-heading">
      <div className="panel">
        <button type="button" className="link-as-text" onClick={onBack}>
          목록으로
        </button>
        <h1 id="detail-heading">요청 상세</h1>

        {state.phase === 'loading' && (
          <div className="state-box" role="status">
            로딩 중...
          </div>
        )}

        {state.phase === 'notfound' && (
          <div className="state-box" role="status">
            <p className="error-text">요청을 찾을 수 없습니다. (404)</p>
          </div>
        )}

        {state.phase === 'error' && (
          <div className="state-box" role="alert">
            <p className="error-text">{state.error.message}</p>
            <button type="button" className="btn" onClick={() => setReloadToken((n) => n + 1)}>
              재시도
            </button>
          </div>
        )}

        {state.phase === 'success' && (
          <dl className="detail-fields">
            <dt>제목</dt>
            <dd>{state.item.title}</dd>
            <dt>설명</dt>
            <dd>{state.item.description === '' ? '—' : state.item.description}</dd>
            <dt>요청자</dt>
            <dd>{state.item.requester}</dd>
            <dt>담당자</dt>
            <dd>{state.item.assignee}</dd>
            <dt>우선순위</dt>
            <dd>{priorityLabel(state.item.priority)}</dd>
            <dt>상태</dt>
            <dd>{statusLabel(state.item.status)}</dd>
            <dt>생성 시각</dt>
            <dd>{formatDateTime(state.item.createdAt)}</dd>
            <dt>수정 시각</dt>
            <dd>{formatDateTime(state.item.updatedAt)}</dd>
          </dl>
        )}
      </div>
    </section>
  );
}
