{"content": "// client/src/App.tsx — 해시 기반 경량 라우팅 (새 의존성·라우터 라이브러리 없음)
import { useEffect, useState } from 'react';
import { RequestList } from './components/RequestList';
import { RequestForm } from './components/RequestForm';
import { RequestDetail } from './components/RequestDetail';

type Route =
  | { name: 'list' }
  | { name: 'create' }
  | { name: 'detail'; id: string };

/** 현재 해시 → 라우트 해석: #/(목록), #/new(등록), #/requests/{id}(상세) */
function parseRoute(): Route {
  const hash = window.location.hash;
  if (hash.startsWith('#/requests/')) {
    const id = decodeURIComponent(hash.slice('#/requests/'.length));
    if (id !== '') {
      return { name: 'detail', id };
    }
  }
  if (hash === '#/new') {
    return { name: 'create' };
  }
  return { name: 'list' };
}

function navigate(to: string) {
  window.location.hash = to;
}

export function App() {
  const [route, setRoute] = useState<Route>(parseRoute);

  useEffect(() => {
    function onHashChange() {
      setRoute(parseRoute());
      window.scrollTo(0, 0);
    }
    window.addEventListener('hashchange', onHashChange);
    return () => {
      window.removeEventListener('hashchange', onHashChange);
    };
  }, []);

  return (
    <main className="app-shell">
      {route.name === 'list' && (
        <RequestList
          onOpenCreate={() => navigate('#/new')}
          onOpenDetail={(id) => navigate(`#/requests/${encodeURIComponent(id)}`)}
        />
      )}
      {route.name === 'create' && (
        <RequestForm
          onCancel={() => navigate('#/')}
          onCreated={(id) => navigate(`#/requests/${encodeURIComponent(id)}`)}
        />
      )}
      {route.name === 'detail' && (
        <RequestDetail key={route.id} id={route.id} onBack={() => navigate('#/')} />
      )}
    </main>
  );
}
