{"content": "1|// client/src/api.ts — fetch 래퍼 (Vite 프록시의 /api 상대 경로 사용, 절대 URL 없음)
2|import type { CreateRequestPayload, ListFilters, RequestList, WorkRequest } from './types';
3|
4|/** 오류 형식: {error:{code,message}} (docs/specification.md API 오류 조항) */
5|export class ApiError extends Error {
6|  readonly status: number;
7|  readonly code: string;
8|
9|  constructor(status: number, code: string, message: string) {
10|    super(message);
11|    this.name = 'ApiError';
12|    this.status = status;
13|    this.code = code;
14|  }
15|}
16|
17|/** 오류 응답 본문 파싱 (본문 형식이 다르면 일반 오류로 통일) */
18|async function toApiError(res: Response): Promise<ApiError> {
19|  let code = 'UNKNOWN_ERROR';
20|  let message = `요청이 실패했습니다. (HTTP ${res.status})`;
21|  try {
22|    const body: unknown = await res.json();
23|    if (isErrorBody(body)) {
24|      code = body.error.code;
25|      message = body.error.message;
26|    }
27|  } catch {
28|    // JSON이 아니면 기본 문구 사용
29|  }
30|  return new ApiError(res.status, code, message);
31|}
32|
33|function isErrorBody(body: unknown): body is { error: { code: string; message: string } } {
34|  if (body === null || typeof body !== 'object') return false;
35|  const error = (body as { error?: unknown }).error;
36|  if (error === null || typeof error !== 'object') return false;
37|  const { code, message } = error as { code?: unknown; message?: unknown };
38|  return typeof code === 'string' && typeof message === 'string';
39|}
40|
41|async function request<T>(path: string, init?: RequestInit): Promise<T> {
42|  let res: Response;
43|  try {
44|    res = await fetch(path, init);
45|  } catch {
46|    // 네트워크 오류는 HTTP 상태와 구분된다
47|    throw new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다. 네트워크 상태를 확인하고 다시 시도하세요.');
48|  }
49|  if (!res.ok) {
50|    throw await toApiError(res);
51|  }
52|  try {
53|    return (await res.json()) as T;
54|  } catch {
55|    throw new ApiError(res.status, 'PARSE_ERROR', '서버 응답을 해석할 수 없습니다.');
56|  }
57|}
58|
59|/** GET /api/requests — 상태·우선순위 AND 필터, total=필터 후 개수 */
60|export function listRequests(filters: ListFilters = {}): Promise<RequestList> {
61|  const params = new URLSearchParams();
62|  if (filters.status) {
63|    params.set('status', filters.status);
64|  }
65|  if (filters.priority) {
66|    params.set('priority', filters.priority);
67|  }
68|  const query = params.toString();
69|  return request<RequestList>(`/api/requests${query ? `?${query}` : ''}`);
70|}
71|
72|/** GET /api/requests/{id} — 상세 (404는 ApiError status=404, code=NOT_FOUND) */
73|export function getRequest(id: string): Promise<WorkRequest> {
74|  return request<WorkRequest>(`/api/requests/${encodeURIComponent(id)}`);
75|}
76|
77|/** POST /api/requests — 등록 (성공 시 201 + 생성된 WorkRequest) */
78|export function createRequest(payload: CreateRequestPayload): Promise<WorkRequest> {
79|  return request<WorkRequest>('/api/requests', {
80|    method: 'POST',
81|    headers: { 'Content-Type': 'application/json' },
82|    body: JSON.stringify(payload),
83|  });
84|}", "total_lines": 84, "file_size": 3068, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

