{"content": "1|// client/src/components/RequestForm.tsx — WF-02 요청 등록 화면
2|import { useState, type FormEvent } from 'react';
3|import { ApiError, createRequest } from '../api';
4|import { PRIORITY_LABELS } from '../labels';
5|import { REQUEST_PRIORITIES, type RequestPriority } from '../types';
6|
7|interface FormValues {
8|  title: string;
9|  description: string;
10|  requester: string;
11|  assignee: string;
12|  priority: '' | RequestPriority;
13|}
14|
15|interface FieldErrors {
16|  title?: string;
17|  description?: string;
18|  requester?: string;
19|  assignee?: string;
20|  priority?: string;
21|}
22|
23|interface Props {
24|  /** 목록으로 돌아가기 (취소) */
25|  onCancel: () => void;
26|  /** POST 201 성공 후 상세 화면으로 이동 */
27|  onCreated: (id: string) => void;
28|}
29|
30|/** Unicode 코드 포인트 기준 길이 (docs/specification.md) */
31|function codePointLength(value: string): number {
32|  return [...value].length;
33|}
34|
35|/** 계약 검증: 필수·길이·공백만 있는 값 */
36|function validate(values: FormValues): FieldErrors {
37|  const errors: FieldErrors = {};
38|
39|  const title = values.title.trim();
40|  if (title.length === 0) {
41|    errors.title = '제목은 필수입니다.';
42|  } else if (codePointLength(title) > 100) {
43|    errors.title = '제목은 100자 이내로 입력하세요.';
44|  }
45|
46|  const description = values.description.trim();
47|  if (codePointLength(description) > 2000) {
48|    errors.description = '설명은 2000자 이내로 입력하세요.';
49|  }
50|
51|  const requester = values.requester.trim();
52|  if (requester.length === 0) {
53|    errors.requester = '요청자는 필수입니다.';
54|  } else if (codePointLength(requester) > 60) {
55|    errors.requester = '요청자는 60자 이내로 입력하세요.';
56|  }
57|
58|  const assignee = values.assignee.trim();
59|  if (assignee.length === 0) {
60|    errors.assignee = '담당자는 필수입니다.';
61|  } else if (codePointLength(assignee) > 60) {
62|    errors.assignee = '담당자는 60자 이내로 입력하세요.';
63|  }
64|
65|  if (values.priority === '') {
66|    errors.priority = '우선순위를 선택하세요.';
67|  }
68|
69|  return errors;
70|}
71|
72|const EMPTY_VALUES: FormValues = {
73|  title: '',
74|  description: '',
75|  requester: '',
76|  assignee: '',
77|  priority: '',
78|};
79|
80|export function RequestForm({ onCancel, onCreated }: Props) {
81|  const [values, setValues] = useState<FormValues>(EMPTY_VALUES);
82|  const [errors, setErrors] = useState<FieldErrors>({});
83|  const [submitting, setSubmitting] = useState(false);
84|  const [serverError, setServerError] = useState<string | null>(null);
85|
86|  // 오류 시 입력 보존: 값을 초기화하지 않고 그대로 유지한다.
87|  function setField<K extends keyof FormValues>(key: K, value: FormValues[K]) {
88|    setValues((prev) => ({ ...prev, [key]: value }));
89|  }
90|
91|  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
92|    event.preventDefault();
93|    if (submitting) {
94|      return; // 재클릭·Enter 중복 제출 방지
95|    }
96|    const nextErrors = validate(values);
97|    setErrors(nextErrors);
98|    setServerError(null);
99|    if (Object.keys(nextErrors).length > 0) {
100|      return;
101|    }
102|    setSubmitting(true);
103|    try {
104|      const created = await createRequest({
105|        title: values.title.trim(),
106|        description: values.description.trim(),
107|        requester: values.requester.trim(),
108|        assignee: values.assignee.trim(),
109|        priority: values.priority as RequestPriority,
110|      });
111|      onCreated(created.id); // 성공 시 상세 화면으로 이동
112|    } catch (error: unknown) {
113|      const message =
114|        error instanceof ApiError
115|          ? error.message
116|          : '서버에 연결할 수 없습니다. 네트워크 상태를 확인하고 다시 시도하세요.';
117|      setServerError(message);
118|      setSubmitting(false);
119|    }
120|  }
121|
122|  const hasError = (key: keyof FieldErrors): boolean => Object.prototype.hasOwnProperty.call(errors, key);
123|
124|  return (
125|    <section aria-labelledby="create-heading">
126|      <div className="panel">
127|        <button type="button" className="link-as-text" onClick={onCancel}>
128|          목록으로
129|        </button>
130|        <h1 id="create-heading">새 업무 요청</h1>
131|
132|        <form noValidate onSubmit={handleSubmit} aria-busy={submitting}>
133|          <div className="form-field">
134|            <label htmlFor="f-title">
135|              제목 <span className="required-mark" aria-hidden="true">*</span>
136|              <span className="sr-only-text">(필수)</span>
137|            </label>
138|            <input
139|              type="text"
140|              id="f-title"
141|              name="title"
142|              value={values.title}
143|              onChange={(e) => setField('title', e.target.value)}
144|              aria-required="true"
145|              aria-invalid={hasError('title')}
146|              aria-describedby={hasError('title') ? 'err-title' : undefined}
147|            />
148|            {hasError('title') && (
149|              <p className="field-error" id="err-title" role="alert">
150|                {errors.title}
151|              </p>
152|            )}
153|          </div>
154|
155|          <div className="form-field">
156|            <label htmlFor="f-description">설명</label>
157|            <textarea
158|              id="f-description"
159|              name="description"
160|              value={values.description}
161|              onChange={(e) => setField('description', e.target.value)}
162|              aria-invalid={hasError('description')}
163|              aria-describedby={hasError('description') ? 'err-description' : undefined}
164|            />
165|            <p className="hint">최대 2000자</p>
166|            {hasError('description') && (
167|              <p className="field-error" id="err-description" role="alert">
168|                {errors.description}
169|              </p>
170|            )}
171|          </div>
172|
173|          <div className="form-field">
174|            <label htmlFor="f-requester">
175|              요청자 <span className="required-mark" aria-hidden="true">*</span>
176|              <span className="sr-only-text">(필수)</span>
177|            </label>
178|            <input
179|              type="text"
180|              id="f-requester"
181|              name="requester"
182|              value={values.requester}
183|              onChange={(e) => setField('requester', e.target.value)}
184|              aria-required="true"
185|              aria-invalid={hasError('requester')}
186|              aria-describedby={hasError('requester') ? 'err-requester' : undefined}
187|            />
188|            {hasError('requester') && (
189|              <p className="field-error" id="err-requester" role="alert">
190|                {errors.requester}
191|              </p>
192|            )}
193|          </div>
194|
195|          <div className="form-field">
196|            <label htmlFor="f-assignee">
197|              담당자 <span className="required-mark" aria-hidden="true">*</span>
198|              <span className="sr-only-text">(필수)</span>
199|            </label>
200|            <input
201|              type="text"
202|              id="f-assignee"
203|              name="assignee"
204|              value={values.assignee}
205|              onChange={(e) => setField('assignee', e.target.value)}
206|              aria-required="true"
207|              aria-invalid={hasError('assignee')}
208|              aria-describedby={hasError('assignee') ? 'err-assignee' : undefined}
209|            />
210|            {hasError('assignee') && (
211|              <p className="field-error" id="err-assignee" role="alert">
212|                {errors.assignee}
213|              </p>
214|            )}
215|          </div>
216|
217|          <fieldset className="form-field" style={{ border: 'none', padding: 0 }}>
218|            <legend>
219|              우선순위 <span className="required-mark" aria-hidden="true">*</span>
220|              <span className="sr-only-text">(필수)</span>
221|            </legend>
222|            <div
223|              className="radio-group"
224|              role="radiogroup"
225|              aria-label="우선순위"
226|              aria-describedby={hasError('priority') ? 'err-priority' : undefined}
227|            >
228|              {REQUEST_PRIORITIES.map((priority) => (
229|                <label className="radio-option" key={priority}>
230|                  <input
231|                    type="radio"
232|                    name="priority"
233|                    value={priority}
234|                    checked={values.priority === priority}
235|                    onChange={() => setField('priority', priority)}
236|                  />
237|                  {PRIORITY_LABELS[priority]}
238|                </label>
239|              ))}
240|            </div>
241|            {hasError('priority') && (
242|              <p className="field-error" id="err-priority" role="alert">
243|                {errors.priority}
244|              </p>
245|            )}
246|          </fieldset>
247|
248|          {serverError && (
249|            <p className="field-error" role="alert">
250|              {serverError}
251|            </p>
252|          )}
253|
254|          <div className="form-actions">
255|            <button type="button" className="btn" onClick={onCancel}>
256|              취소
257|            </button>
258|            <button type="submit" className="btn btn-primary" disabled={submitting}>
259|              {submitting ? '등록 중...' : '등록'}
260|            </button>
261|          </div>
262|        </form>
263|      </div>
264|    </section>
265|  );
266|}", "total_lines": 266, "file_size": 9116, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// client/src/components/RequestDetail.tsx — WF-03 상세 화면 (읽기 전용)
2|// PATCH 수정·상태 변경은 다음 교시 범위이므로 이 화면에는 해당 조작을 두지 않는다.
3|import { useCallback, useEffect, useState } from 'react';
4|import { ApiError, getRequest } from '../api';
5|import { formatDateTime, priorityLabel, statusLabel } from '../labels';
6|import type { WorkRequest } from '../types';
7|
8|type DetailState =
9|  | { phase: 'loading' }
10|  | { phase: 'notfound' }
11|  | { phase: 'error'; error: ApiError }
12|  | { phase: 'success'; item: WorkRequest };
13|
14|interface Props {
15|  id: string;
16|  /** 목록으로 돌아가기 */
17|  onBack: () => void;
18|}
19|
20|export function RequestDetail({ id, onBack }: Props) {
21|  const [state, setState] = useState<DetailState>({ phase: 'loading' });
22|  const [reloadToken, setReloadToken] = useState(0);
23|
24|  const load = useCallback(() => {
25|    setState({ phase: 'loading' });
26|    getRequest(id)
27|      .then((item) => setState({ phase: 'success', item }))
28|      .catch((error: unknown) => {
29|        if (error instanceof ApiError && error.status === 404) {
30|          setState({ phase: 'notfound' });
31|        } else {
32|          setState({
33|            phase: 'error',
34|            error:
35|              error instanceof ApiError
36|                ? error
37|                : new ApiError(0, 'NETWORK_ERROR', '서버에 연결할 수 없습니다.'),
38|          });
39|        }
40|      });
41|  }, [id]);
42|
43|  useEffect(() => {
44|    load();
45|  }, [load, reloadToken]);
46|
47|  return (
48|    <section aria-labelledby="detail-heading">
49|      <div className="panel">
50|        <button type="button" className="link-as-text" onClick={onBack}>
